-- changeset marcopremier:16 dbms:cloudspanner
-- comment: Persist quarantined raw-upload correction candidates and fence state.

SET PROTO_DESCRIPTORS = '';

START BATCH DDL;

ALTER PROTO BUNDLE INSERT (
  `wfa.measurement.internal.edpaggregator.CorrectionCandidate.Classification`,
  `wfa.measurement.internal.edpaggregator.CorrectionCandidate.State`,
  `wfa.measurement.internal.edpaggregator.CorrectionCandidate.Decision`,
  `wfa.measurement.internal.edpaggregator.VidLabelingEvictionFenceState`
) UPDATE (
  `wfa.measurement.internal.edpaggregator.RawImpressionUploadState`
);

ALTER TABLE VidLabelingEvictionFence ADD COLUMN State
  `wfa.measurement.internal.edpaggregator.VidLabelingEvictionFenceState`;

CREATE TABLE CorrectionCandidate (
  DataProviderResourceId STRING(63) NOT NULL,
  CorrectionCandidateId STRING(36) NOT NULL,
  RawImpressionUploadResourceId STRING(63) NOT NULL,
  CreateRequestId STRING(36) NOT NULL,
  Classification `wfa.measurement.internal.edpaggregator.CorrectionCandidate.Classification` NOT NULL,
  PriorManifestDigest BYTES(MAX) NOT NULL,
  CurrentManifestDigest BYTES(MAX) NOT NULL,
  State `wfa.measurement.internal.edpaggregator.CorrectionCandidate.State` NOT NULL,
  Decision `wfa.measurement.internal.edpaggregator.CorrectionCandidate.Decision` NOT NULL,
  SupersedingCorrectionCandidateId STRING(36),
  UploadHealingOperationId STRING(36),
  ExpireTime TIMESTAMP NOT NULL,
  AdvanceRequestIds ARRAY<STRING(36)> NOT NULL,
  AdvanceRequestFingerprints ARRAY<BYTES(MAX)> NOT NULL,
  CreateTime TIMESTAMP NOT NULL OPTIONS (allow_commit_timestamp = true),
  UpdateTime TIMESTAMP NOT NULL OPTIONS (allow_commit_timestamp = true),
) PRIMARY KEY (DataProviderResourceId, CorrectionCandidateId);

CREATE UNIQUE INDEX CorrectionCandidateByRawImpressionUpload
  ON CorrectionCandidate(DataProviderResourceId, RawImpressionUploadResourceId);

CREATE UNIQUE INDEX CorrectionCandidateByCreateRequestId
  ON CorrectionCandidate(DataProviderResourceId, CreateRequestId);

CREATE INDEX CorrectionCandidateByStateAndCreateTime
  ON CorrectionCandidate(DataProviderResourceId, State, CreateTime, CorrectionCandidateId);

RUN BATCH;
